base.src/billing/report.py:
def summarise_orders(orders):
    totals = {}
    for order in orders:
        key = order["customer"]
        totals[key] = totals.get(key, 0) + order["amount"] * order["quantity"]
    return sorted(totals.items(), key=lambda item: -item[1])

